def backfill_import_operations(apps, schema_editor):
    """Digest existing bytes and anchor historical terminal rows. Never purge."""
    anchor = timezone.now()
    for model_name in ('MspImportJob', 'P6ImportJob'):
        model = apps.get_model('schedule', model_name)
        identifiers = list(model.objects.order_by('pk').values_list('pk', flat=True))
        for start in range(0, len(identifiers), 100):
            for row in model.objects.filter(pk__in=identifiers[start:start + 100]):
                changed = []
                payload = bytes(row.file_data) if row.file_data else b''
                if payload and not row.source_sha256:
                    row.source_sha256 = hashlib.sha256(payload).hexdigest()
                    row.source_size = len(payload)
                    changed.extend(['source_sha256', 'source_size'])
                if row.status in ('done', 'failed') and row.retention_anchor_at is None:
                    row.retention_anchor_at = anchor
                    row.retention_anchor_source = 'legacy_backfill'
                    changed.extend(['retention_anchor_at', 'retention_anchor_source'])
                if changed:
                    row.save(update_fields=changed)
    slot = apps.get_model('schedule', 'ImportProcessingSlot')
    slot.objects.get_or_create(slot_number=1)


def reverse_import_operations(apps, schema_editor):
    """Drop seeded capacity only. Purged bytes cannot be restored."""
    slot = apps.get_model('schedule', 'ImportProcessingSlot')
    slot.objects.filter(slot_number=1).delete()


